<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('settings.manage');$t=(int)$user['tenant_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');if($name){db()->prepare("UPDATE tenants SET name=:n,document=:d,phone=:p,email=:e,updated_at=NOW() WHERE id=:t")->execute(['n'=>$name,'d'=>trim($_POST['document']??'')?:null,'p'=>trim($_POST['phone']??'')?:null,'e'=>trim($_POST['email']??'')?:null,'t'=>$t]);audit('settings.tenant_update','tenant',$t,[]);flash('success','Dados da clínica atualizados.');redirect('settings/index.php');}}$st=db()->prepare("SELECT * FROM tenants WHERE id=:t");$st->execute(['t'=>$t]);$tenant=$st->fetch();$sub=\App\Core\Tenant::currentSubscription($t);layout('Configurações',function()use($tenant,$sub){?><div class="page-head"><div><span class="eyebrow">Configurações</span><h1>Clínica</h1><p>Dados institucionais e resumo da assinatura.</p></div></div><div class="grid-2"><form method="post" class="card form-grid"><?=csrf_field()?><h2>Dados da clínica</h2><div class="field"><label>Nome</label><input name="name" value="<?=e($tenant['name'])?>" required></div><div class="form-row"><div class="field"><label>CPF/CNPJ</label><input name="document" value="<?=e($tenant['document']??'')?>"></div><div class="field"><label>Telefone</label><input name="phone" value="<?=e($tenant['phone']??'')?>"></div></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?=e($tenant['email']??'')?>"></div><button class="button">Salvar</button></form><section class="card"><h2>Assinatura</h2><div class="kpi"><small>Plano</small><strong><?=e($sub['plan_name']??'—')?></strong></div><p>Status: <span class="status <?=e($sub['status']??'')?>"><?=e($sub['status']??'sem assinatura')?></span></p><p>Período atual: <?=e($sub['current_period_start']?date('d/m/Y',strtotime($sub['current_period_start'])):'—')?> a <?=e($sub['current_period_end']?date('d/m/Y',strtotime($sub['current_period_end'])):'—')?></p><a class="button secondary" href="<?=e(url('billing/index.php'))?>">Ver plano e limites</a></section></div><?php },[]);
